@extends('layout.app') @section('title','New Sales Order') @section('content')<div class="page-head"><div><span class="eyebrow">SALES</span><h1>New sales order</h1><p class="muted">Stock is checked and deducted atomically when the order is created.</p></div></div><div class="panel form-panel"><form method="POST" action="{{ route('orders.store') }}">@csrf<label>Customer<select name="customer_id"><option value="">Walk-in customer</option>@foreach($customers as $customer)<option value="{{ $customer->id }}" @selected(old('customer_id')==$customer->id)>{{ $customer->name }} — {{ $customer->phone ?: $customer->email }}</option>@endforeach</select></label><label>Order date<input type="date" name="order_date" value="{{ old('order_date',now()->toDateString()) }}" required></label><label>Delivery address<textarea name="delivery_address" rows="3">{{ old('delivery_address') }}</textarea></label><div class="panel-head"><h2>Order items</h2><button type="button" class="btn btn-light" id="add-item">＋ Add item</button></div><div id="items"></div><template id="item-template"><div class="order-line grid-3 panel" data-item-row><label>Product<select data-product name="items[__INDEX__][product_id]" required><option value="">Select product</option>@foreach($products as $product)<option value="{{ $product->id }}">{{ $product->product_name }} — {{ $product->stock_quantity }} available · UGX {{ number_format($product->product_price,2) }}</option>@endforeach</select></label><label>Quantity<input data-quantity type="number" min="1" name="items[__INDEX__][quantity]" value="1" required></label><div><span class="muted">&nbsp;</span><button type="button" class="btn btn-light remove-item" style="margin-top:7px">Remove</button></div></div></template><div class="grid-2"><label>Discount<input type="number" min="0" step="0.01" name="discount_amount" value="{{ old('discount_amount',0) }}"></label><label>Tax<input type="number" min="0" step="0.01" name="tax_amount" value="{{ old('tax_amount',0) }}"></label></div><label>Notes<textarea name="notes" rows="3">{{ old('notes') }}</textarea></label><div class="form-actions"><a class="btn btn-light" href="{{ route('orders.index') }}">Cancel</a><button class="btn btn-primary">Create order</button></div></form></div><script>document.addEventListener('DOMContentLoaded',()=>{const items=document.getElementById('items'),tpl=document.getElementById('item-template').innerHTML;let index=0;const add=()=>{items.insertAdjacentHTML('beforeend',tpl.replaceAll('__INDEX__',index++));};document.getElementById('add-item').addEventListener('click',add);items.addEventListener('click',e=>{if(e.target.classList.contains('remove-item')){e.target.closest('[data-item-row]').remove();if(!items.children.length)add();}});add();});</script>@endsection
